() => {
  const byRel = {};
  document.querySelectorAll('link[rel]').forEach(l => { const k = l.getAttribute('rel'); byRel[k] = (byRel[k]||0)+1; });
  const metas = {};
  document.querySelectorAll('meta[name],meta[property]').forEach(m => { const k = m.getAttribute('name') || m.getAttribute('property'); metas[k] = (metas[k]||0)+1; });
  const ld = document.querySelectorAll('script[type="application/ld+json"]');
  const txt = Array.from(ld).map(s => s.textContent).join('\n');
  return {
    url: location.href,
    title: document.title,
    canonical: document.querySelector('link[rel=canonical]')?.href,
    ogUrl: document.querySelector('meta[property="og:url"]')?.content,
    ogImage: document.querySelector('meta[property="og:image"]')?.content,
    twitterImage: document.querySelector('meta[name="twitter:image"]')?.content,
    lang: document.documentElement.lang,
    dir: document.documentElement.dir,
    h1Count: document.querySelectorAll('h1').length,
    h1s: Array.from(document.querySelectorAll('h1')).map(h => h.textContent.trim().slice(0,60)),
    h2Count: document.querySelectorAll('h2').length,
    h3Count: document.querySelectorAll('h3').length,
    linkRelCounts: byRel,
    metaCounts: metas,
    ldScripts: ld.length,
    jsonLdUrls: (txt.match(/https:\/\/[^"\s]+/g)) || [],
    bodyMentionsParked: document.body.textContent.includes('tehranlaser.ir'),
    description: document.querySelector('meta[name="description"]')?.content?.slice(0,80),
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth
  };
}

async () => {
  const r = await fetch('https://tehran-laser.samerkhaldounmarefi.workers.dev/sitemap.xml');
  const t = await r.text();
  return { status: r.status, locCount: (t.match(/<loc>/g)||[]).length, parkedLocs: (t.match(/https:\/\/tehranlaser\.ir[^<]*/g)||[]).length, sample: t.slice(0,600) };
}
